// Industry template runtime (HVAC, Plumbing, Electrical, Roofing, Cleaning).
// HTML is generated by scripts/build-industries.mjs; this file wires the data-* widgets.
import { initSite, gsap, ScrollTrigger, reduceMotion } from '../../ds/site.js';
import { mount3D } from '../../ds/fx3d.js';
import { Flip } from 'gsap/Flip';
import { $, $$, initHeadings, initMagnetic, initTilt, radioGroup } from './motion.js';
import './industry.css';

gsap.registerPlugin(Flip);
initSite();
const mm = gsap.matchMedia();
initHeadings(mm);
initMagnetic();
initTilt();
const json = (el, key) => JSON.parse(el.dataset[key]);

// ---------------------------------------------------------------------------
// Hero: 3D demand field behind the signature card + entrance choreography
// ---------------------------------------------------------------------------
let field = null;
mount3D($('[data-3d="field"]'), { scene: 'field', theme: 'light' }).then((api) => (field = api));
mm.add('(prefers-reduced-motion: no-preference)', () => {
  gsap.from('.ind-hero__visual > .hw, .ind-hero__visual > .picker', { y: 40, opacity: 0, rotationX: -8, duration: 1.3, ease: 'expo.out', delay: 0.35, transformPerspective: 900 });
  gsap.from('.ind-hero__visual', { clipPath: 'inset(8% 8% 8% 8% round 28px)', duration: 1.4, ease: 'expo.out', delay: 0.1 });
});

// HVAC · season dial
const modes = $('[data-modes]');
if (modes) {
  const data = json(modes, 'modes');
  const dial = $('[data-dial]', modes);
  const C = 2 * Math.PI * 88;
  const num = $('[data-dial-num]', modes);
  const show = (i) => {
    const m = data[i];
    modes.dataset.modeId = m.id;
    dial.setAttribute('stroke-dashoffset', (C * (1 - m.value / 100)).toFixed(1));
    $('[data-dial-week]', modes).textContent = m.week;
    m.stats.forEach(([v], k) => ($(`[data-stat="${k}"]`, modes).textContent = v));
    const o = { v: parseInt(num.textContent, 10) || 0 };
    if (reduceMotion) num.textContent = `${m.value}%`;
    else gsap.to(o, { v: m.value, duration: 0.9, ease: 'power3.out', onUpdate: () => (num.textContent = `${Math.round(o.v)}%`) });
    field?.setProgress(i / (data.length - 1));
  };
  const btns = $$('[data-mode]', modes);
  radioGroup(btns, (i) => show(i));
  modes.dataset.modeId = data[btns.findIndex((b) => b.getAttribute('aria-checked') === 'true')].id;
}

// Plumbing · incoming call
const call = $('[data-call]');
if (call) {
  const result = $('[data-call-result]', call);
  const reset = $('[data-call-reset]', call);
  $$('[data-call-act]', call).forEach((b) =>
    b.addEventListener('click', () => {
      call.classList.add('is-done');
      result.textContent = result.dataset[b.dataset.callAct];
      reset.hidden = false;
      reset.focus();
      if (!reduceMotion) gsap.from(result, { y: 12, opacity: 0, duration: 0.6, ease: 'expo.out' });
    }),
  );
  reset.addEventListener('click', () => {
    call.classList.remove('is-done');
    result.textContent = '';
    reset.hidden = true;
    $('[data-call-act="answered"]', call).focus();
  });
}

// Electrical · breaker panel (role=switch)
const panel = $('[data-switches]');
if (panel) {
  const breakers = $$('.breaker', panel);
  const readout = $('[data-switch-readout]', panel);
  const update = () => {
    const on = breakers.filter((b) => b.getAttribute('aria-checked') === 'true');
    readout.textContent = on.length
      ? `${on.length} of ${breakers.length} circuits live: ${on.map((b) => $('.t-label-sm', b).textContent).join(', ')}.`
      : 'All circuits off: no projects in the pipeline.';
    field?.setProgress(on.length / breakers.length);
  };
  breakers.forEach((b) =>
    b.addEventListener('click', () => {
      const on = b.getAttribute('aria-checked') !== 'true';
      b.setAttribute('aria-checked', String(on));
      $('.breaker__state', b).textContent = on ? 'ON' : 'OFF';
      update();
    }),
  );
  update();
}

// Roofing · storm alert rows play in sequence
const alert = $('[data-alert]');
if (alert && !reduceMotion) {
  gsap.from($$('.hw__alert-rows li', alert), { x: -16, opacity: 0, duration: 0.7, ease: 'expo.out', stagger: 0.35, delay: 0.9 });
}

// ---------------------------------------------------------------------------
// Segment tools
// ---------------------------------------------------------------------------
$$('[data-slider]').forEach((el) => {
  const ranges = json(el, 'ranges');
  const input = $('input', el);
  const max = Number(el.dataset.max);
  const set = () => {
    const v = Number(input.value);
    const r = ranges.find((x) => v <= x.upTo) || ranges.at(-1);
    $('[data-slider-value]', el).textContent = `${v}${v >= max ? '+' : ''}${el.dataset.suffix}`;
    $('[data-slider-eyebrow]', el).textContent = r.eyebrow.toUpperCase();
    $('[data-slider-title]', el).textContent = r.title;
    $('[data-slider-text]', el).textContent = r.text;
    input.setAttribute('aria-valuetext', `${v} years: ${r.eyebrow}`);
    el.style.setProperty('--fill', `${((v - input.min) / (max - input.min)) * 100}%`);
  };
  input.addEventListener('input', set);
  set();
});

// Plumbing · call log: filter (Flip) + expandable rows
$$('[data-calllog]').forEach((el) => {
  const items = $$('.call', el);
  const filters = [() => true, (c) => c.dataset.seg === 'Residential', (c) => c.dataset.seg === 'Commercial', (c) => c.dataset.kind === 'Emergency'];
  radioGroup($$('[data-filter]', el), (i) => {
    const state = Flip.getState(items);
    items.forEach((c) => (c.hidden = !filters[i](c)));
    if (!reduceMotion) Flip.from(state, { duration: 0.5, ease: 'power2.inOut', absolute: true, onEnter: (els) => gsap.fromTo(els, { opacity: 0 }, { opacity: 1, duration: 0.4 }), onLeave: (els) => gsap.to(els, { opacity: 0, duration: 0.25 }) });
  });
  $$('.call__row', el).forEach((b) => b.addEventListener('click', () => b.setAttribute('aria-expanded', String(b.getAttribute('aria-expanded') !== 'true'))));
});

// Electrical · bid board: move cards between columns (Flip)
$$('[data-board]').forEach((el) => {
  const cols = $$('.board__col', el);
  const status = $('[data-board-status]', el);
  const names = json(el, 'cols');
  const sync = () => {
    cols.forEach((c, k) => ($(`[data-count-col="${k}"]`, el).textContent = $$('.bid', c).length));
    $$('.bid', el).forEach((card) => {
      const k = cols.indexOf(card.closest('.board__col'));
      $('[data-dir="-1"]', card).disabled = k === 0;
      $('[data-dir="1"]', card).disabled = k === cols.length - 1;
    });
  };
  el.addEventListener('click', (e) => {
    const b = e.target.closest('.bid__move');
    if (!b) return;
    const card = b.closest('.bid');
    const k = cols.indexOf(card.closest('.board__col')) + Number(b.dataset.dir);
    if (k < 0 || k >= cols.length) return;
    const state = Flip.getState($$('.bid', el));
    $('.board__list', cols[k]).append(card);
    sync();
    if (!reduceMotion) Flip.from(state, { duration: 0.55, ease: 'power3.inOut' });
    status.textContent = `${$('.t-label-md', card).textContent} moved to ${names[k]}.`;
    const same = $(`[data-dir="${b.dataset.dir}"]`, card);
    (same.disabled ? $(`[data-dir="${-b.dataset.dir}"]`, card) : same).focus();
  });
  sync();
});

// Roofing · review checklist
$$('[data-checklist]').forEach((el) => {
  const boxes = $$('input', el);
  const bar = $('[data-check-bar]', el);
  const status = $('[data-check-status]', el);
  const set = () => {
    const n = boxes.filter((b) => b.checked).length;
    bar.style.setProperty('--value', `${(n / boxes.length) * 100}%`);
    status.textContent = n === boxes.length ? 'Every job asks for a review that mentions all four.' : `${n} of ${boxes.length} covered in your review requests.`;
  };
  boxes.forEach((b) => b.addEventListener('change', set));
  set();
});

// "What they type (or ask AI)": typewriter on first view
mm.add('(prefers-reduced-motion: no-preference)', () => {
  $$('[data-typewriter]').forEach((q) => {
    const text = q.textContent;
    q.setAttribute('aria-label', text);
    ScrollTrigger.create({
      trigger: q,
      start: 'top 85%',
      once: true,
      onEnter: () => {
        const o = { n: 0 };
        q.classList.add('is-typing');
        gsap.to(o, { n: text.length, duration: text.length * 0.035, ease: 'none', onUpdate: () => (q.textContent = text.slice(0, Math.round(o.n))), onComplete: () => q.classList.remove('is-typing') });
      },
    });
  });
});

// ---------------------------------------------------------------------------
// Exclusive modules
// ---------------------------------------------------------------------------
$$('[data-capacity]').forEach((el) => {
  const slots = $$('.slot[data-before]', el);
  const legend = json(el, 'legend');
  const summary = json(el, 'summary');
  const show = (state) => {
    slots.forEach((s, i) => {
      const code = s.dataset[state];
      s.className = `slot slot--${code}`;
      $('[data-slot-label]', s).textContent = legend[code];
      if (!reduceMotion) gsap.fromTo(s, { scale: 0.6, opacity: 0.4 }, { scale: 1, opacity: 1, duration: 0.45, ease: 'back.out(2)', delay: (i % 5) * 0.03 + Math.floor(i / 5) * 0.05 });
    });
    summary.forEach((x, i) => ($(`[data-sum="${i}"]`, el).textContent = x[state]));
  };
  radioGroup($$('[data-state]', el), (i, b) => show(b.dataset.state));
  // Scroll: once the grid is in view, the week fills itself in
  if (!reduceMotion) ScrollTrigger.create({ trigger: el, start: 'top 45%', once: true, onEnter: () => $$('[data-state]', el)[1].click() });
});

mm.add('(prefers-reduced-motion: no-preference)', () => {
  const from = (targets, trigger, vars) => {
    const els = $$(targets);
    const { start = 'top 80%', ...rest } = vars;
    if (els.length) gsap.from(els, { ...rest, scrollTrigger: { trigger: $(trigger), start } });
  };
  from('[data-bars] .mbars__bar', '[data-bars]', { scaleY: 0, duration: 1, ease: 'expo.out', stagger: 0.07 });
  from('[data-leaks] .leaks__bar', '[data-leaks]', { scaleX: 0.2, opacity: 0, duration: 1, ease: 'expo.out', stagger: 0.12 });
  from('.cal__bar', '.cal', { scaleY: 0, transformOrigin: '50% 100%', duration: 0.9, ease: 'expo.out', stagger: 0.025, start: 'top 75%' });
  from('.strip__stage', '[data-strip]', { y: 20, opacity: 0, duration: 0.7, ease: 'expo.out', stagger: 0.06, start: 'top 85%' });
});

$$('[data-scrub]').forEach((el) => {
  const input = $('input', el);
  const times = json(el, 'times');
  const time = $('[data-scrub-time]', el);
  const set = (v) => {
    const i = Math.round(v);
    time.textContent = times[i];
    input.setAttribute('aria-valuetext', times[i]);
    $$('.scrub__step', el).forEach((s) => {
      const k = Number(s.dataset.i);
      s.classList.toggle('is-on', k <= i);
      s.classList.toggle('is-now', k === i);
    });
  };
  input.addEventListener('input', () => set(Number(input.value)));
  set(0);
  // Desktop: the clock also advances with scroll through the section (user can still drag)
  mm.add('(min-width: 901px) and (prefers-reduced-motion: no-preference)', () => {
    const st = ScrollTrigger.create({
      trigger: el,
      start: 'top 70%',
      end: 'bottom 60%',
      onUpdate: (self) => {
        const v = Math.round(self.progress * (times.length - 1));
        if (Number(input.value) !== v) {
          input.value = v;
          set(v);
        }
      },
    });
    return () => st.kill();
  });
});

$$('[data-meter]').forEach((el) => {
  const input = $('input', el);
  const states = json(el, 'states');
  const slots = $$('.meter__slot', el);
  const set = () => {
    const v = Number(input.value);
    const booked = Math.round((v / 100) * slots.length);
    slots.forEach((s, i) => s.classList.toggle('is-booked', i < booked));
    const st = states.find((s) => v >= s.min);
    $('[data-meter-value]', el).textContent = `${v}%`;
    $('[data-meter-title]', el).textContent = `${v}% booked · ${slots.length - booked} open slots → ${st.t.toLowerCase()}`;
    $('[data-meter-text]', el).textContent = st.d;
    input.setAttribute('aria-valuetext', `${v}% booked, ${st.t}`);
  };
  input.addEventListener('input', set);
  set();
});

$$('[data-project]').forEach((el) => {
  const projects = json(el, 'projects');
  radioGroup($$('[data-project-i]', el), (i) => {
    projects[i].facts.forEach(([l, v], k) => {
      const dd = $(`[data-fact="${k}"]`, el);
      dd.textContent = v;
      dd.previousElementSibling.textContent = l;
      if (!reduceMotion) gsap.fromTo(dd, { y: 8, opacity: 0 }, { y: 0, opacity: 1, duration: 0.4, delay: k * 0.04, ease: 'expo.out' });
    });
  });
});

// ---------------------------------------------------------------------------
// Demand calendar: hover / focus a month, toggle a series
// ---------------------------------------------------------------------------
$$('[data-calendar]').forEach((el) => {
  const values = json(el, 'values');
  const names = json(el, 'names');
  const tip = $('[data-cal-tip]', el);
  const cols = $$('.cal__col', el);
  const months = $$('.cal__month', el);
  const label = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const show = (m) => {
    cols.forEach((c, k) => c.classList.toggle('is-hover', k === m));
    months.forEach((c, k) => c.classList.toggle('is-hover', k === m));
    if (m < 0) return (tip.hidden = true);
    tip.hidden = false;
    tip.innerHTML = '';
    tip.append(Object.assign(document.createElement('strong'), { textContent: label[m] }));
    names.forEach((n, s) => tip.append(Object.assign(document.createElement('div'), { textContent: `${n}: ${values[s][m]}` })));
    tip.style.left = `${Math.min(88, Math.max(12, ((m + 0.5) / 12) * 100))}%`;
  };
  cols.forEach((c, m) => {
    c.addEventListener('pointerenter', () => show(m));
    c.addEventListener('pointerleave', () => show(-1));
  });
  months.forEach((b, m) => {
    b.addEventListener('focus', () => show(m));
    b.addEventListener('blur', () => show(-1));
    b.addEventListener('pointerenter', () => show(m));
    b.addEventListener('pointerleave', () => show(-1));
    b.addEventListener('click', () => show(m));
  });
  const keys = $$('.cal__key', el);
  keys.forEach((k) =>
    k.addEventListener('click', () => {
      const on = k.getAttribute('aria-pressed') !== 'true';
      keys.forEach((x) => x.setAttribute('aria-pressed', String(x === k && on)));
      if (on) el.dataset.focus = k.dataset.series;
      else delete el.dataset.focus;
    }),
  );
});

// ---------------------------------------------------------------------------
// Growth System block widgets
// ---------------------------------------------------------------------------
$$('[data-rules]').forEach((el) => {
  const input = $('input', el);
  const mins = json(el, 'ruleMins');
  const rules = $$('.rule', el);
  const set = () => {
    const v = Number(input.value);
    const i = mins.findIndex((m) => v >= m);
    rules.forEach((r, k) => r.classList.toggle('is-active', k === i));
    $('[data-rules-value]', el).textContent = `${v}%`;
    input.setAttribute('aria-valuetext', `${v}% booked: ${$('.t-label-xs', rules[i]).textContent.toLowerCase()}`);
  };
  input.addEventListener('input', set);
  set();
});

$$('[data-sfunnel]').forEach((el) => {
  const details = json(el, 'details');
  const steps = $$('.sfunnel__step', el);
  const show = (i) => {
    steps.forEach((s, k) => s.setAttribute('aria-pressed', String(k === i)));
    $('[data-sf-label]', el).textContent = `SELECTED STAGE · ${details[i].label.toUpperCase()}`;
    $('[data-sf-value]', el).textContent = details[i].value;
    $('[data-sf-detail]', el).textContent = details[i].detail;
  };
  steps.forEach((s, i) => s.addEventListener('click', () => show(i)));
  show(Math.max(0, steps.findIndex((s) => s.getAttribute('aria-pressed') === 'true')));
  if (!reduceMotion) gsap.from($$('.sfunnel__bar', el), { scaleY: 0, transformOrigin: '50% 100%', duration: 1, ease: 'expo.out', stagger: 0.07, scrollTrigger: { trigger: el, start: 'top 80%' } });
});
